def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_def = op.count('D')
    my_def = my.count('D')
    last_me = my[-1]
    last_op = op[-1]

    if opp_def == 0:
        if n >= 18 and (n % 7 == 0) and rng.random() < 0.5:
            return 'D'
        return 'C'

    if op[-1] == 'D':
        if n >= 2 and op[-2] == 'D':
            if n >= 4 and op[-3] == 'D' and op[-4] == 'D':
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'D'

    window = op[-10:] if n >= 10 else op
    recent_def = window.count('D')
    recent_len = len(window)

    if recent_def == 0:
        if n >= 25 and recent_len >= 10:
            if rng.random() < 0.08:
                return 'D'
        if n >= 60 and rng.random() < 0.12:
            return 'D'
        return 'C'

    if recent_def == 1 and recent_len >= 10:
        if op[-1] == 'C' and op[-2] == 'C':
            return 'C'
        return 'C'

    if recent_def >= recent_len // 2:
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    last10 = op[-10:]
    if last10.count('D') >= 3:
        if op[-1] == 'C' and op[-2] == 'C' and rng.random() < 0.35:
            return 'D'
        return 'C'

    return 'C'
